<div class="tab-content"><div id="salary-pane" class="tab-pane fade show active"><x-hris.table id="salary-table" endpoint="/hr/references/salaries" filters :columns="[['key'=>'grade','label'=>'Grade'],['key'=>'step','label'=>'Step'],['key'=>'monthly_salary','label'=>'Monthly salary'],['key'=>'effective_from','label'=>'Effective from'],['key'=>'effective_to','label'=>'Effective to']]" :actions="[['name'=>'edit','label'=>'Edit'],['name'=>'archive','label'=>'End','danger'=>true]]"><x-hris.field name="grade" label="Filter grade" type="number" min="1" max="99" data-table-filter/></x-hris.table></div>
