@push('scripts')<script>document.addEventListener('hris:ready',()=>{const salaries=document.querySelector('#salary-table'),holidays=document.querySelector('#holiday-table'),salaryForm=document.querySelector('#salary-form'),holidayForm=document.querySelector('#holiday-form');HRIS.bindForm(salaryForm,{success:()=>salaries.table.load()});HRIS.bindForm(holidayForm,{success:()=>holidays.table.load()});function handle(table,form,base,modal){table.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='edit'){HRIS.fillForm(form,{...row,agency_wide:String(row.agency_wide),employee_ids:(row.employees||[]).map(x=>x.id)});form.dataset.endpoint=`${base}/${row.id}`;form.dataset.method='PUT';HRIS.openModal(modal)}else if(await HRIS.confirm('End or archive this reference? Historical records remain unchanged.')){HRIS.feedback((await HRIS.request(`${base}/${row.id}/archive`,{method:'PATCH'})).message);table.table.load()}}catch(e){HRIS.feedback(e.message,true)}})}handle(salaries,salaryForm,'/hr/references/salaries','salary-modal');handle(holidays,holidayForm,'/hr/references/holidays','holiday-modal')});</script>@endpush
